('AV-001', 'officiel', 'action-verite', 1, '[J1], action : raconte ta pire galère de vacances. Si quelqu''un ici était du voyage, il ou elle raconte sa version. Vérité : t''es-tu déjà endormi·e dans les transports au point de rater ton arrêt ? Si quelqu''un ici était avec toi et ne t''a pas réveillé·e, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-002', 'officiel', 'action-verite', 1, '[J1], action : raconte la soirée où tu as rencontré quelqu''un ici. La personne concernée raconte son premier souvenir de toi. Vérité : as-tu déjà oublié le prénom de quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-003', 'officiel', 'action-verite', 1, '[J1], action : raconte la fois où tu as cuisiné pour le groupe et que ça a mal tourné. Si quelqu''un ici a goûté, il ou elle donne une note. Vérité : as-tu déjà fait semblant d''aimer un plat chez quelqu''un ici ? Si le cuisinier est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-016', 'officiel', 'action-verite', 1, '[J1], action : raconte ton pire anniversaire. Si quelqu''un ici y était, il ou elle ajoute ce que tu as oublié. Vérité : as-tu déjà oublié l''anniversaire de quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-017', 'officiel', 'action-verite', 1, '[J1], action : raconte la fois où tu t''es perdu·e en voyage. Si quelqu''un ici était avec toi, il ou elle dit à qui la faute. Vérité : as-tu déjà dormi dans une voiture ? Si quelqu''un ici dormait à côté, il ou elle raconte la nuit.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-018', 'officiel', 'action-verite', 1, '[J1], action : raconte le pire week-end en groupe que tu as vécu. Si quelqu''un ici en était, il ou elle balance qui était le pire. Vérité : as-tu déjà emprunté un vêtement à quelqu''un ici sans le rendre ? Si le propriétaire est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-019', 'officiel', 'action-verite', 1, '[J1], action : raconte le pire jeu de soirée auquel tu as joué. Si quelqu''un ici y a joué avec toi, il ou elle dit qui a triché. Vérité : as-tu déjà triché à un jeu contre quelqu''un ici ? Si ta victime est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-020', 'officiel', 'action-verite', 1, '[J1], action : raconte ton pire fou rire au mauvais moment. Si quelqu''un ici l''a déclenché, vous buvez tous les deux. Vérité : t''es-tu déjà fait engueuler par un voisin pour le bruit ? Si c''était pendant une soirée avec quelqu''un ici, il ou elle raconte la scène.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-021', 'officiel', 'action-verite', 1, '[J1], action : raconte la fois où tu as pris le mauvais train, bus ou métro. Si quelqu''un ici était avec toi, il ou elle dit jusqu''où vous êtes allés. Vérité : as-tu déjà fini les restes de quelqu''un ici sans demander ? Si la personne est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-022', 'officiel', 'action-verite', 1, '[J1], action : raconte ta pire gaffe devant les parents de quelqu''un. Si c''étaient les parents de quelqu''un ici, il ou elle raconte la tête qu''ils ont faite. Vérité : as-tu déjà menti sur ton heure d''arrivée à quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-004', 'officiel', 'action-verite', 2, '[J1], action : raconte ta pire chute en soirée. Si quelqu''un ici t''a relevé·e, vous buvez tous les deux. Vérité : as-tu déjà fini une soirée sans savoir où tu étais ? Si quelqu''un ici y était, c''est lui ou elle qui raconte à ta place.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-005', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as perdu tes clés en soirée. Si quelqu''un ici t''a hébergé·e ou aidé·e à rentrer, vous buvez tous les deux. Vérité : combien de fois as-tu dit « je bois plus jamais » ? Si quelqu''un ici t''a vu·e recommencer le soir même, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-006', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu t''es fait sortir d''un bar ou d''une boîte. Si quelqu''un ici s''est fait sortir avec toi, vous buvez tous les deux. Vérité : as-tu déjà dû payer un truc que tu avais cassé en soirée ? Si quelqu''un ici a payé à ta place, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-023', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as perdu tes potes en soirée. Si l''un d''eux est ici, il ou elle raconte où on t''a retrouvé·e. Vérité : t''es-tu déjà endormi·e en pleine soirée ? Si quelqu''un ici t''a vu·e, il ou elle décrit la position.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-024', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as dormi chez quelqu''un du groupe après une soirée. Ton hôte raconte dans quel état tu es arrivé·e. Vérité : as-tu déjà vomi en soirée ? Si quelqu''un ici t''a tenu les cheveux, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-025', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as appelé quelqu''un à l''aide à 5 h du matin. Si c''était quelqu''un ici, il ou elle raconte l''appel. Vérité : as-tu déjà menti à tes parents sur l''endroit où tu dormais ? Si quelqu''un ici t''a servi d''alibi, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-026', 'officiel', 'action-verite', 2, '[J1], action : raconte ton pire réveil après une soirée. Si quelqu''un ici était à côté de toi, il ou elle raconte ce qu''il a vu en premier. Vérité : es-tu déjà rentré·e d''une soirée au lever du soleil ? Si quelqu''un ici était avec toi, il ou elle raconte la fin de la nuit.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-027', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as ramené quelqu''un du groupe complètement bourré. Si la personne est ici, elle boit avec toi. Vérité : t''a-t-on déjà ramené·e chez toi en soirée ? Si c''était quelqu''un ici, il ou elle raconte comment ça s''est passé.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-028', 'officiel', 'action-verite', 2, '[J1], action : raconte une bêtise de soirée qu''un pote a dû couvrir. Si c''était quelqu''un ici, vous buvez tous les deux. Vérité : as-tu déjà vidé le frigo de quelqu''un en rentrant de soirée ? Si c''était chez quelqu''un ici, il ou elle dit ce qui manquait le lendemain.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-029', 'officiel', 'action-verite', 2, '[J1], action : raconte la fois où tu as raté un train, un avion ou un rendez-vous à cause d''une soirée. Si quelqu''un ici en est responsable, vous buvez tous les deux. Vérité : as-tu déjà dormi ailleurs que dans un lit après une soirée ? Si quelqu''un ici t''a retrouvé·e, il ou elle raconte où.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-007', 'officiel', 'action-verite', 3, '[J1], action : raconte ton pire premier date. Si quelqu''un ici t''a servi d''excuse pour t''enfuir, vous buvez tous les deux. Vérité : as-tu déjà eu un crush sur quelqu''un ici ? Si la personne le savait, vous buvez tous les deux.', '{couple}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-008', 'officiel', 'action-verite', 3, '[J1], action : raconte ta rupture la plus pathétique. Si quelqu''un ici t''a consolé·e, il ou elle raconte dans quel état tu étais. Vérité : as-tu déjà écrit à un·e ex en soirée ? Si quelqu''un ici t''a vu·e faire sans t''arrêter, vous buvez tous les deux.', '{ex}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-009', 'officiel', 'action-verite', 3, '[J1], action : raconte ton pire râteau. Si quelqu''un ici était témoin, il ou elle raconte la réaction de l''autre. Vérité : as-tu déjà dragué quelqu''un sur qui un pote d''ici avait des vues ? Si ce pote est là, vous buvez tous les deux.', '{couple,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-030', 'officiel', 'action-verite', 3, '[J1], action : raconte la fois où tu as joué les entremetteurs pour quelqu''un ici. La personne concernée dit si tu l''as aidée ou sabotée. Vérité : as-tu déjà embrassé quelqu''un en soirée parce que tes potes te poussaient ? Si l''un d''eux est ici, vous buvez tous les deux.', '{couple}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-031', 'officiel', 'action-verite', 3, '[J1], action : raconte ton date le plus gênant. Si quelqu''un ici t''a appelé·e pour te sortir de là, vous buvez tous les deux. Vérité : as-tu déjà menti à un date sur ce que tu faisais dans la vie ? Si quelqu''un ici a couvert ton mensonge, vous buvez tous les deux.', '{couple}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-032', 'officiel', 'action-verite', 3, '[J1], action : raconte la fois où tu as recroisé un·e ex en soirée. Si quelqu''un ici y était, il ou elle raconte comment tu as réagi. Vérité : es-tu déjà retourné·e avec un·e ex après avoir juré que c''était fini ? Si quelqu''un ici t''avait prévenu·e, vous buvez tous les deux.', '{ex}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-033', 'officiel', 'action-verite', 3, '[J1], action : raconte la fois où tu as dû expliquer à tes colocs ou à ta famille qui sortait de ta chambre le matin. Si quelqu''un ici était ce coloc, il ou elle raconte sa version. Vérité : as-tu déjà été jaloux·se du/de la partenaire de quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{couple,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-034', 'officiel', 'action-verite', 3, '[J1], action : raconte le pire endroit où tu as embrassé quelqu''un. Si quelqu''un ici était à côté, il ou elle raconte la scène. Vérité : as-tu déjà demandé à quelqu''un ici de t''arranger le coup avec un crush ? Si cette personne est là, elle dit si ça a marché.', '{couple}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-035', 'officiel', 'action-verite', 3, '[J1], action : raconte la fois où tu as fini la soirée avec quelqu''un que tu ne supportais pas en début de soirée. Si quelqu''un ici a vu le retournement, il ou elle raconte. Vérité : as-tu déjà fait semblant de ne pas voir un·e ex en soirée ? Si quelqu''un ici t''a grillé·e, vous buvez tous les deux.', '{couple,ex}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-036', 'officiel', 'action-verite', 3, '[J1], action : raconte ton pire réveil à côté de quelqu''un. Si quelqu''un ici t''a vu·e partir avec cette personne, il ou elle raconte la soirée. Vérité : as-tu déjà eu une histoire avec quelqu''un rencontré grâce à un pote d''ici ? Si l''entremetteur est là, vous buvez tous les deux.', '{couple}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-010', 'officiel', 'action-verite', 4, '[J1], action : raconte la pire soirée que quelqu''un ici a organisée. L''organisateur ou l''organisatrice a 10 secondes pour se défendre. Vérité : as-tu déjà dit du mal de quelqu''un ici à quelqu''un d''autre ici ? Si ton confident est là, vous buvez tous les deux.', '{avis,secrets}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-011', 'officiel', 'action-verite', 4, '[J1], action : raconte un secret qu''on t''a confié en soirée, sans dire de qui. Si la personne est ici et se reconnaît, elle boit. Vérité : as-tu déjà eu honte de quelqu''un ici en soirée ? Si la personne est là, vous buvez tous les deux.', '{avis,secrets}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-012', 'officiel', 'action-verite', 4, '[J1], action : raconte la fois où quelqu''un ici t''a lâché·e en pleine soirée. La personne concernée a 10 secondes pour se défendre. Vérité : as-tu déjà fait semblant d''être malade pour éviter la soirée de quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-037', 'officiel', 'action-verite', 4, '[J1], action : raconte la fois où tu as payé pour tout le monde sans jamais être remboursé·e. Si le mauvais payeur est ici, il ou elle boit double. Vérité : dois-tu encore de l''argent à quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{argent,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-038', 'officiel', 'action-verite', 4, '[J1], action : raconte le pire comportement de quelqu''un ici en soirée, sans le nommer. Si la personne se reconnaît, elle boit. Vérité : as-tu déjà été jaloux·se d''une amitié dans ce groupe ? Si les deux amis sont là, vous buvez tous les trois.', '{avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-039', 'officiel', 'action-verite', 4, '[J1], action : raconte la fois où tu as balancé quelqu''un ici sans le vouloir. La victime raconte les conséquences. Vérité : as-tu déjà raconté une soirée de ce groupe à quelqu''un qui n''aurait pas dû savoir ? Si quelqu''un ici en a fait les frais, vous buvez tous les deux.', '{avis,secrets}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-040', 'officiel', 'action-verite', 4, '[J1], action : laisse le groupe te trouver un surnom, que tout le monde utilisera jusqu''à la fin de la partie. Chaque fois que quelqu''un se trompe de surnom, il boit 1 gorgée. Vérité : le truc le plus gênant que tu as fait pour impressionner quelqu''un ici ?', '{avis}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('AV-041', 'officiel', 'action-verite', 4, '[J1], action : raconte la fois où tu as couvert quelqu''un ici auprès de son ou sa partenaire. La personne couverte boit avec toi. Vérité : as-tu déjà menti à quelqu''un ici pour échapper à une soirée ? Si la personne a fini par le savoir, vous buvez tous les deux.', '{couple,secrets,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-042', 'officiel', 'action-verite', 4, '[J1], action : raconte ta pire dispute avec quelqu''un ici. La personne concernée donne sa version en 10 secondes. Vérité : as-tu déjà lu un message par-dessus l''épaule de quelqu''un ici ? Si la personne est là, vous buvez tous les deux.', '{avis,secrets}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-043', 'officiel', 'action-verite', 4, '[J1], action : raconte la fois où tu es allé·e au boulot directement depuis une soirée. Si quelqu''un ici y était, il ou elle raconte dans quel état tu es parti·e. Vérité : as-tu déjà menti sur ton CV ? Si quelqu''un ici t''a servi de fausse référence, vous buvez tous les deux.', '{}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-013', 'officiel', 'action-verite', 5, '[J1], action : raconte ton pire coup d''un soir, sans détails. Si quelqu''un ici t''a vu·e partir avec la personne, il ou elle raconte le départ. Vérité : donne ton bodycount. Si quelqu''un ici en fait partie, vous buvez tous les deux.', '{sexe,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-014', 'officiel', 'action-verite', 5, '[J1], action : avoue le dernier truc que tu as dit dans le dos de quelqu''un ici. Si la personne est là, vous buvez tous les deux. Vérité : ton pire moment gênant au lit, sans détails ? Si quelqu''un ici était concerné, il ou elle confirme ou dément.', '{secrets,avis,sexe}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-015', 'officiel', 'action-verite', 5, '[J1], action : donne trois raisons catastrophiques de quitter son/sa copine. Vérité : la chose la plus illégale que tu as faite sans te faire prendre ? Si quelqu''un ici était ton complice, vous buvez tous les deux.', '{couple,transgressions}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-044', 'officiel', 'action-verite', 5, '[J1], action : désigne la personne ici avec qui tu sortirais si tu devais choisir. Si c''est réciproque, vous buvez tous les deux. Vérité : ton plus gros fantasme, sans détails ? Si quelqu''un ici le connaissait déjà, il ou elle boit.', '{couple,sexe,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published'),
('AV-045', 'officiel', 'action-verite', 5, '[J1], action : raconte la fois où tu as couché avec quelqu''un que tu n''aurais pas dû, sans dire qui. Si la personne est ici, elle boit avec toi. Vérité : as-tu déjà eu un crush sur le/la partenaire de quelqu''un ici ? Si la personne concernée est là, vous buvez tous les deux.', '{couple,sexe,avis}', NULL, false, true, NULL, NULL, NULL, NULL, 'published');
