('SEN-013', 'officiel', 'sentence', 1, '[J1], tu bois. Le jeu t''aime bien, c''est tout.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-014', 'officiel', 'sentence', 1, '[J1] boit. Le jeu a hésité entre toi et le chat. Le chat a gagné.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-015', 'officiel', 'sentence', 1, '[J1], tu bois parce que tu lis la notice avant de monter un meuble. Personne ne fait ça.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-016', 'officiel', 'sentence', 1, '[J1], tu bois. Prends-le comme un cadeau.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-017', 'officiel', 'sentence', 1, '[J1] boit pour avoir dit « c''est la dernière » il y a trois verres.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-003', 'officiel', 'sentence', 2, '[J1] boit parce qu''[il/elle/iel] a une tête à mettre du ketchup sur les pâtes.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-004', 'officiel', 'sentence', 2, '[J1], tu bois pour toutes les fois où tu as dit « j''arrive dans 5 minutes ».', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-018', 'officiel', 'sentence', 2, '[J1] boit parce qu''[il/elle/iel] dit « on se capte » et ne capte jamais personne.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-019', 'officiel', 'sentence', 2, '[J1], tu bois pour tous les vocaux de trois minutes que tu as envoyés.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-020', 'officiel', 'sentence', 2, '[J1] boit. On ne sait pas encore pourquoi, mais ça viendra.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-021', 'officiel', 'sentence', 2, '[J1], tu bois pour toutes les fois où tu as dit « on fait ça la semaine prochaine ».', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-022', 'officiel', 'sentence', 2, '[J1] boit parce qu''[il/elle/iel] range ses chaussettes par couleur. Ou pas. Dans le doute.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-023', 'officiel', 'sentence', 2, '[J1], tu bois pour ton dernier pas de danse. Il méritait une sanction.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
('SEN-024', 'officiel', 'sentence', 2, '[J1] boit parce qu''[il/elle/iel] a ri trop fort à la dernière blague.', '{}', NULL, false, false, NULL, NULL, NULL, NULL, 'published'),
